window.kbPageData["views/entry/k-843675050c632a63"] = {"key":"entry/k-843675050c632a63","state":{"route":"entry/k-843675050c632a63"},"node":{"id":"k-843675050c632a63","mode":"k","title":"党性修养","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["增强共产党人的党性","党性修养与自我革命"],"qs":["政治理论必刷100题#81","政治理论必刷100题#83"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["party"],"主类":["概念与词义"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"党性修养是共产党员通过理论学习、党内政治生活和实践锻炼，自觉增强党性并把党性要求落实到行动中的过程。","review":{"title":"党性修养","type":"概念与词义","definition":"党性修养是共产党员通过理论学习、党内政治生活和实践锻炼，自觉增强党性并把党性要求落实到行动中的过程。","explanation":"2025年6月30日，习近平在中共中央政治局第二十一次集体学习时强调，推进自我革命必须固本培元、增强党性。增强党性重在坚定理想信念，也要求铸牢对党忠诚、厚植为民情怀、纯正道德品质、保持清正廉洁。党员可在履职实践和党内政治生活中锻炼党性，自觉接受教育和监督。","basis":"据关联原题及所列出处编释。","references":[{"source":"primary","location":"加强党性修养"}],"related":["k-1632ca8680fadb9b","k-ce1e1cc79bdb2c0f"],"examFocus":{"政治理论必刷100题#81":"区分推进党的自我革命的根本保证、党性要求和实践举措，核对题中各项要求所处的层次。","政治理论必刷100题#83":"核对纠治“四风”相关论述，分清党性修养的重点、作风建设的作用与自我革命在跳出历史周期率中的定位。"}},"aspects":[{"title":"党的自我革命中的党性要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。A项所述固本培元、增强党性是推进自我革命的要求。答案C误将完善党内法规体系列为根本保证。所附解析引用2024年第24期《求是》刊载的《深入推进党的自我革命》，其中明确以坚持党中央集中统一领导为根本保证。","evidence":"推进自我革命，必须固本培元、增强党性","qids":["政治理论必刷100题#81"]},{"unit":"Q2","role":"直接考查","use":"本题在落实中央八项规定精神、纠治“四风”长效机制的语境中考查坚定理想信念对增强党性的重要性，D项表述成立。题目选不正确项，答案A错在把自我革命列为跳出历史周期率的第一个答案。按2025年6月30日讲话，自我革命是第二个答案。","evidence":"推进自我革命，必须固本培元、增强党性。增强党性，重在坚定理想信念","qids":["政治理论必刷100题#83"]}]}],"sources":[{"id":"956d0ec506441030","label":"增强共产党人的党性","topic":"党政制度与理论","category":"非时政","text":"3.增强共产党人的党性\n《决定》把“增强共产党人的党性”摆在战略任务部署的第一部分，并且从 5 个方面\n作出了具体部署。一是强化对党忠诚教育。深刻领悟“两个确立”的决定性意义，增强“四\n个意识”、坚定“四个自信”、做到“两个维护”，严明党的政治纪律和政治规矩，净化\n党内政治生态。二是坚持用党的创新理论凝心铸魂。把学习、领悟、运用党的创新理论作\n为加强党性修养的根本途径，深入学习贯彻习近平党建思想，丰富理论学习教育方式，弘\n扬马克思主义学风。三是用党的优良传统和中华优秀传统文化涵养党性。发扬党的优良作\n风，传承红色基因，赓续共产党人精神血脉，挖掘用好中华优秀传统文化中的道德观念。\n四是在实践中锤炼党性。在贯彻落实党中央决策部署、完成急难险重任务、应对重大风浪\n考验中锤炼党性，在处理是和非、公和私、得和失等关系中磨砺党性，发挥党内政治生活\n“大熔炉”作用。五是加强党性鉴别。把党性作为干部考察和党员民主评议的重要内容，\n在干部选拔任用和评优评先中用好党性鉴别结果。","source":{"doc":"41195a191a57c1c36332","first":14,"last":14,"page":14,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#81":{"paper":"政治理论必刷100题","n":81,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",25],"asrc":["国省考政治理论必刷100题.pdf",84],"card":"c712792d79101a72fad0396e","links":[{"id":"k-843675050c632a63","role":"直接考查","why":"题目核对固本培元、增强党性在推进自我革命中的要求。"}]},"政治理论必刷100题#83":{"paper":"政治理论必刷100题","n":83,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",25],"asrc":["国省考政治理论必刷100题.pdf",86],"card":"c83e1df1ec6aa0a017612506","links":[{"id":"k-843675050c632a63","role":"直接考查","why":"题目直接核对坚定理想信念在增强党性中的地位。"}]}},"terms":{"k-1632ca8680fadb9b":{"id":"k-1632ca8680fadb9b","mode":"k","type":"制度与规则","title":"党的自我革命“九个以”","qs":[],"count":3},"k-ce1e1cc79bdb2c0f":{"id":"k-ce1e1cc79bdb2c0f","mode":"k","type":"事实与事件","title":"跳出历史周期率的两个答案","qs":[],"count":3}},"references":{"primary":{"name":"习近平在中共中央政治局第二十一次集体学习时强调坚持从抓作风入手推进全面从严治党把新时代党的自我革命要求进一步落实到位————头条——中央纪委国家监委网站","url":"https://www.ccdi.gov.cn/toutiaon/202506/t20250630_431710_m.html"}},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-843675050c632a63":[["政治理论必刷100题#81"],["政治理论必刷100题#83"]]}};
